final class WifiPanel {
 final Activity a;final WifiManager wifi;final LinearLayout box,networks;TextView status; View scanButton; Switch toggle;boolean registered=false;String pending="";Dialog dialog;
 final BroadcastReceiver receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if(WifiManager.SUPPLICANT_STATE_CHANGED_ACTION.equals(i.getAction())&&i.getIntExtra(WifiManager.EXTRA_SUPPLICANT_ERROR,-1)==WifiManager.ERROR_AUTHENTICATING){pending="";status.setText("Password rejected. Select the network to retry.");}else render();}};
 int d(int n){return UI.dp(a,n);}
 WifiPanel(Activity activity,LinearLayout target){a=activity;box=target;wifi=(WifiManager)a.getApplicationContext().getSystemService(Context.WIFI_SERVICE);
  LinearLayout header=new LinearLayout(a);header.setGravity(Gravity.CENTER_VERTICAL);box.addView(header,new LinearLayout.LayoutParams(-1,d(38)));
  TextView title=UI.text(a,"Wi-Fi",22,-1);title.setGravity(Gravity.LEFT);header.addView(title,new LinearLayout.LayoutParams(0,-1,1));
  scanButton=UI.iconButton(a,"Refresh networks","refresh",()->scan());header.addView(scanButton,new LinearLayout.LayoutParams(d(30),d(30)));
  toggle=new Switch(a);toggle.setContentDescription("Wi-Fi on or off");toggle.setChecked(wifi!=null&&wifi.isWifiEnabled());LinearLayout.LayoutParams toggleParams=new LinearLayout.LayoutParams(d(43),d(28));toggleParams.leftMargin=d(12);header.addView(toggle,toggleParams);toggle.setThumbTintList(android.content.res.ColorStateList.valueOf(-1));toggle.setTrackTintList(android.content.res.ColorStateList.valueOf(0xff777777));toggle.setOnClickListener(v->{if(wifi!=null&&!wifi.setWifiEnabled(toggle.isChecked())){toggle.setChecked(wifi.isWifiEnabled());status.setText("Android rejected the Wi-Fi change");}});
  status=UI.text(a,"Finding networks…",11,0xff999999);status.setGravity(Gravity.LEFT);LinearLayout.LayoutParams stateParams=new LinearLayout.LayoutParams(-1,d(32));stateParams.topMargin=d(8);box.addView(status,stateParams);
  ScrollView scroll=new ScrollView(a);scroll.setVerticalScrollBarEnabled(false);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,0,1);sp.topMargin=d(10);box.addView(scroll,sp);networks=new LinearLayout(a);networks.setOrientation(LinearLayout.VERTICAL);scroll.addView(networks);
  IntentFilter f=new IntentFilter();for(String action:new String[]{WifiManager.SCAN_RESULTS_AVAILABLE_ACTION,WifiManager.NETWORK_STATE_CHANGED_ACTION,WifiManager.WIFI_STATE_CHANGED_ACTION,WifiManager.SUPPLICANT_STATE_CHANGED_ACTION})f.addAction(action);a.registerReceiver(receiver,f);registered=true;scan();
 }
 void focusScan(){scanButton.requestFocus();}
 void scan(){if(wifi==null){status.setText("Wi-Fi hardware unavailable");return;}if(a.checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){a.requestPermissions(new String[]{android.Manifest.permission.ACCESS_FINE_LOCATION},41);status.setText("Allow Wi-Fi discovery to see nearby networks");return;}render();try{if(!wifi.startScan())status.setText("Showing last scan. Android may limit frequent scans.");}catch(SecurityException e){status.setText("Enable Location for Wi-Fi discovery");}}
 String current(){try{String s=wifi.getConnectionInfo().getSSID();return s==null||s.equals("<unknown ssid>")?"":unquote(s);}catch(Exception e){return "";}}
 static String unquote(String s){return s!=null&&s.startsWith("\"")&&s.endsWith("\"")?s.substring(1,s.length()-1):s;}
 static String quote(String s){return "\""+s.replace("\\","\\\\").replace("\"","\\\"")+"\"";}
 void render(){if(wifi==null)return;String focused="";View previous=a.getCurrentFocus();if(previous!=null&&previous.getTag() instanceof String)focused=(String)previous.getTag();networks.removeAllViews();String active=current();status.setText(!wifi.isWifiEnabled()?"Wi-Fi is off":!pending.isEmpty()?"Connecting to "+pending+"…":active.isEmpty()?"Select a network":"Connected");if(!active.isEmpty()&&active.equals(pending)){pending="";status.setText("Connected");}
  toggle.setChecked(wifi.isWifiEnabled());if(!wifi.isWifiEnabled())return;try{LinkedHashMap<String,ScanResult> unique=new LinkedHashMap<>();List<ScanResult> results=new ArrayList<>(wifi.getScanResults());results.sort((x,y)->Integer.compare(y.level,x.level));for(ScanResult r:results){if(!r.SSID.isEmpty())unique.putIfAbsent(r.SSID+security(r),r);}if(!active.isEmpty())row(active+"\nConnected",()->details(active),active);for(ScanResult r:unique.values()){if(r.SSID.equals(active))continue;row(r.SSID+"\n"+security(r)+" · "+(WifiManager.calculateSignalLevel(r.level,4)+1)+"/4",()->choose(r),r.SSID);}if(unique.isEmpty()){TextView t=UI.text(a,"No networks found. Enable Location for Wi-Fi discovery, then scan again.",15,0xffbbbbbb);networks.addView(t,new LinearLayout.LayoutParams(-1,d(110)));row("Enable discovery",()->a.startActivity(new Intent(Settings.ACTION_LOCATION_SOURCE_SETTINGS)),"location");}if(!focused.isEmpty())for(int i=0;i<networks.getChildCount();i++)if(focused.equals(networks.getChildAt(i).getTag()))networks.getChildAt(i).requestFocus();}catch(SecurityException e){status.setText("Wi-Fi discovery permission is required");}}
 void row(String name,Runnable action,String tag){boolean connected=name.endsWith("\nConnected");LinearLayout item=new LinearLayout(a);item.setGravity(Gravity.CENTER_VERTICAL);item.setPadding(d(12),d(9),d(12),d(9));item.setFocusable(true);item.setFocusableInTouchMode(true);item.setClickable(true);item.setTag(tag);item.setContentDescription(name);UI.Icon icon=new UI.Icon(a,"wifi");item.addView(icon,new LinearLayout.LayoutParams(d(17),d(17)));
  LinearLayout texts=new LinearLayout(a);texts.setOrientation(LinearLayout.VERTICAL);LinearLayout.LayoutParams tx=new LinearLayout.LayoutParams(0,-2,1);tx.leftMargin=d(12);item.addView(texts,tx);String[] lines=name.split("\n",2);TextView title=UI.text(a,lines[0],13,0xffeeeeee);title.setSingleLine(true);title.setEllipsize(android.text.TextUtils.TruncateAt.END);title.setGravity(Gravity.LEFT);texts.addView(title,new LinearLayout.LayoutParams(-1,d(20)));TextView sub=UI.text(a,lines.length>1?lines[1]:"",10,0xff999999);sub.setGravity(Gravity.LEFT);texts.addView(sub,new LinearLayout.LayoutParams(-1,d(16)));if(connected){TextView check=UI.text(a,"✓",16,-1);item.addView(check,new LinearLayout.LayoutParams(d(18),-2));}
  item.setBackground(UI.bg(connected?0xff222222:0x00171717,connected?0xff555555:0));item.setOnFocusChangeListener((v,f)->{item.setBackground(UI.bg(f?0xff2a2a2a:connected?0xff222222:0x00171717,f?-1:connected?0xff555555:0));item.animate().alpha(f?1:.88f).setDuration(120).start();});item.setOnClickListener(v->action.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,d(56));p.bottomMargin=d(8);networks.addView(item,p);}
 String security(ScanResult r){String c=r.capabilities;return c.contains("EAP")?"Enterprise":c.contains("WEP")?"WEP":c.contains("PSK")?"Secured":c.contains("SAE")?"WPA3":"Open";}
 WifiConfiguration saved(String ssid){try{List<WifiConfiguration> c=wifi.getConfiguredNetworks();if(c!=null)for(WifiConfiguration n:c)if(ssid.equals(unquote(n.SSID)))return n;}catch(SecurityException ignored){}return null;}
 void choose(ScanResult r){String type=security(r);if(type.equals("Enterprise")||type.equals("WPA3")||type.equals("WEP")){status.setText(type+" networks need advanced setup; WPA/WPA2 and open networks are supported here.");return;}WifiConfiguration old=saved(r.SSID);if(old!=null){new AlertDialog.Builder(a).setTitle(r.SSID).setItems(new String[]{"Connect with saved password","Enter a new password"},(d,n)->{if(n==0)activate(old.networkId,r.SSID);else password(r);}).show();return;}if(type.equals("Open")){new AlertDialog.Builder(a).setTitle("Connect to "+r.SSID+"?").setMessage("This network has no password.").setPositiveButton("Connect",(d,n)->connect(r,"")).setNegativeButton("Cancel",null).show();}else password(r);}
 void password(ScanResult r){LinearLayout content=new LinearLayout(a);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(d(24),d(12),d(24),d(8));EditText input=new EditText(a);input.setSingleLine(true);input.setHint("Password");input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);input.setSaveEnabled(false);content.addView(input,new LinearLayout.LayoutParams(-1,d(44)));CheckBox show=new CheckBox(a);show.setText("Show password");show.setOnCheckedChangeListener((b,v)->{input.setTransformationMethod(v?null:android.text.method.PasswordTransformationMethod.getInstance());input.setSelection(input.length());});content.addView(show);
  AlertDialog prompt=new AlertDialog.Builder(a).setTitle(r.SSID).setView(content).setNegativeButton("Cancel",null).setPositiveButton("Connect",null).create();dialog=prompt;prompt.setOnShowListener(v->{prompt.getButton(-1).setOnClickListener(w->{String pass=input.getText().toString();if(pass.length()<8||pass.length()>63){input.setError("Use 8–63 characters");return;}connect(r,pass);input.setText("");prompt.dismiss();});input.requestFocus();prompt.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_VISIBLE);((InputMethodManager)a.getSystemService(Context.INPUT_METHOD_SERVICE)).showSoftInput(input,InputMethodManager.SHOW_IMPLICIT);});prompt.setOnDismissListener(v->{input.setText("");dialog=null;});prompt.show();}
 void connect(ScanResult r,String pass){try{WifiConfiguration c=new WifiConfiguration();c.SSID=quote(r.SSID);if(security(r).equals("Open"))c.allowedKeyManagement.set(WifiConfiguration.KeyMgmt.NONE);else{c.allowedKeyManagement.set(WifiConfiguration.KeyMgmt.WPA_PSK);c.preSharedKey=quote(pass);}WifiConfiguration old=saved(r.SSID);int id;if(old!=null){c.networkId=old.networkId;id=wifi.updateNetwork(c);}else id=wifi.addNetwork(c);if(id<0){status.setText("Android rejected this network configuration");return;}activate(id,r.SSID);}catch(SecurityException e){status.setText("Android denied Wi-Fi configuration access");}}
 void activate(int id,String name){try{if(wifi.enableNetwork(id,true)){pending=name;status.setText("Connecting to "+name+"…");wifi.reconnect();}else status.setText("Android could not select that network");}catch(SecurityException e){status.setText("Android denied Wi-Fi connection access");}}
 void details(String ssid){new AlertDialog.Builder(a).setTitle(ssid).setMessage("Connected · "+wifi.getConnectionInfo().getLinkSpeed()+" Mbps").setPositiveButton("Done",null).show();}
 void close(){if(registered){a.unregisterReceiver(receiver);registered=false;}if(dialog!=null)dialog.dismiss();}
}
